def _authored_text(metadata: dict, *keys: str) -> str | None:
    """The first non-empty string among `keys` in an input's own frontmatter."""
    for key in keys:
        value = metadata.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


